{
  "findings": [
    {
      "check_id": "CKV2_AWS_6",
      "title": "S3 public access block is missing",
      "resource": "aws_s3_bucket.cloudtrail_logs",
      "severity": "MEDIUM",
      "explanation": "The bucket has no account-level or bucket-level controls in this file preventing public ACLs or public bucket policies. A future policy or ACL change could therefore expose sensitive CloudTrail logs."
    },
    {
      "check_id": "CKV_AWS_21",
      "title": "S3 bucket versioning is disabled",
      "resource": "aws_s3_bucket.cloudtrail_logs",
      "severity": "MEDIUM",
      "explanation": "Without versioning, CloudTrail log objects cannot be recovered from accidental deletion or overwrite. Versioning adds protection for the integrity and availability of audit records."
    },
    {
      "check_id": "CKV_AWS_18",
      "title": "S3 access logging is not enabled",
      "resource": "aws_s3_bucket.cloudtrail_logs",
      "severity": "MEDIUM",
      "explanation": "Access to the bucket containing security audit records is not logged in this file. This reduces visibility into requests against the CloudTrail log repository."
    },
    {
      "check_id": "CKV_AWS_145",
      "title": "S3 bucket does not use KMS encryption by default",
      "resource": "aws_s3_bucket.cloudtrail_logs",
      "severity": "MEDIUM",
      "explanation": "The bucket has no explicit KMS-based default encryption configuration. KMS encryption provides additional key-level access control and auditing for sensitive CloudTrail logs."
    },
    {
      "check_id": "CKV_AWS_70",
      "title": "S3 bucket does not enforce encrypted transport",
      "resource": "aws_s3_bucket.cloudtrail_logs",
      "severity": "MEDIUM",
      "explanation": "No bucket policy denies requests made without TLS, so authenticated clients could submit requests over insecure transport. CloudTrail log data should only be accessed through HTTPS."
    }
  ],
  "patched_code": "data \"aws_caller_identity\" \"current\" {}\n\nresource \"aws_s3_bucket\" \"cloudtrail_logs\" {\n  bucket = \"fleet-management-gps-tracking-system-cloudtrail-${random_string.bucket_suffix.result}\"\n}\n\nresource \"aws_s3_bucket_public_access_block\" \"cloudtrail_logs\" {\n  bucket = aws_s3_bucket.cloudtrail_logs.id\n\n  block_public_acls       = true\n  block_public_policy     = true\n  ignore_public_acls      = true\n  restrict_public_buckets = true\n}\n
